        if type(item) == "RestaurantFilter":
            if 'Israeli' in item.cuisine_type:
                israeli_restaurant_names.append(item.restaurant_name)
        elif type(item) == "dict":
            if 'Israeli' in item.get('cuisine_type', ''):
                israeli_restaurant_names.append(item.get('restaurant_name', ''))
