    restaurant_location = address_result.strip()
else:
    restaurant_location = str(restaurant_address)

print(f"Found Israeli restaurant: {best_restaurant_name}")
print(f"Address: {restaurant_location}")
print(f"Reminder for Nov 14: Dinner at {best_restaurant_name} at {restaurant_location}")
