class CurrentYearSchema(BaseModel):
    year: int

current_year_query = "What is the current year?"
current_year_result = query_ai_assistant(current_year_query, CurrentYearSchema)

current_year = 2024
if type(current_year_result) == "CurrentYearSchema":
    current_year = current_year_result.year
elif type(current_year_result) == "dict":
    current_year = current_year_result.get('year', 2024)
else:
    try:
        current_year = int(str(current_year_result).strip())
    except:
        current_year = 2024

target_date = f"{current_year}-11-14"

paris_restaurants = get_all_restaurants_in_city("Paris")
if not paris_restaurants:
    raise ValueError("No restaurants found in Paris")

restaurant_names = [name.strip() for name in paris_restaurants.replace('\n', ',').split(',') if name.strip()]
cuisine_types = get_cuisine_type_for_restaurants(restaurant_names)

class IsraeliRestaurantSchema(BaseModel):
    restaurants: list[str]

israeli_query = f"List the names of all restaurants that serve Israeli cuisine from the following list of restaurants and their cuisines: {cuisine_types}"
israeli_result = query_ai_assistant(israeli_query, IsraeliRestaurantSchema)

israeli_names = []
if type(israeli_result) == "IsraeliRestaurantSchema":
    israeli_names = israeli_result.restaurants
elif type(israeli_result) == "dict":
    israeli_names = israeli_result.get('restaurants', [])
else:
    if type(israeli_result) == "str":
        israeli_names = [name.strip() for name in israeli_result.split(',') if name.strip()]

if not israeli_names:
    raise ValueError("No Israeli restaurants found in Paris")

ratings_reviews = get_rating_reviews_for_restaurants(israeli_names)

class BestRestaurantSchema(BaseModel):
    name: str

best_query = f"From the following ratings and reviews, identify the restaurant with the best rating and reviews: {ratings_reviews}"
best_result = query_ai_assistant(best_query, BestRestaurantSchema)

best_restaurant_name = ""
if type(best_result) == "BestRestaurantSchema":
    best_restaurant_name = best_result.name
elif type(best_result) == "dict":
    best_restaurant_name = best_result.get('name', '')
else:
    best_restaurant_name = str(best_result).strip()

if not best_restaurant_name:
    raise ValueError("Could not determine the best Israeli restaurant")

address_result = get_restaurants_address([best_restaurant_name])

